    if (gmsg_load_uint(data + 0 + 2, 1, GMSG_ENDIAN_BIG) != (uint64_t)gmsg_crc8_nrsc5_compute(data + 0, 2)) return GMSG_ERR_BAD_CHECKSUM;
    if (gmsg_load_uint(data + 3 + 2, 1, GMSG_ENDIAN_BIG) != (uint64_t)gmsg_crc8_nrsc5_compute(data + 3, 2)) return GMSG_ERR_BAD_CHECKSUM;
    out->data = data;
