/* ==== protocol MeasurementResponse ================================================================= */

void sensirion_sht4x_measurement_response_any_view_print(const sensirion_sht4x_measurement_response_any_view* v, gmsg_printer* p) {
    switch (v->kind) {
        case SENSIRION_SHT4X_MEASUREMENT_RESPONSE_MEASUREMENT: sensirion_sht4x_measurement_view_print(&v->as.measurement, p); break;
        default: gmsg_print_text(p, "<none>", 6); break;
    }
}

void sensirion_sht4x_measurement_response_any_message_print(const sensirion_sht4x_measurement_response_any_message* v, gmsg_printer* p) {
    switch (v->kind) {
        case SENSIRION_SHT4X_MEASUREMENT_RESPONSE_MEASUREMENT: sensirion_sht4x_measurement_print(&v->as.measurement, p); break;
        default: gmsg_print_text(p, "<none>", 6); break;
    }
}

static const gmsg_fixed_config sensirion_sht4x_measurement_response_framing_ = {{{0}, 0}, 6, {false, 0, 0, 0, 0, {0}, {0}, {0}}, 0};
static gmsg_frame_scan sensirion_sht4x_measurement_response_scan_(const uint8_t* b, size_t n) { return gmsg_scan_fixed(b, n, &sensirion_sht4x_measurement_response_framing_); }

/* A validated frame split into its parts (pointers into the frame buffer). */
typedef struct sensirion_sht4x_measurement_response_frame_ {
    const uint8_t* body;
    size_t body_size;
} sensirion_sht4x_measurement_response_frame_;

/* Validate one complete frame (as delimited by the scanner) and split it into header and body. */
static gmsg_error sensirion_sht4x_measurement_response_open_(const uint8_t* frame, size_t size, sensirion_sht4x_measurement_response_frame_* f) {
    gmsg_error e = GMSG_OK;
    (void)e;
    const size_t interior_n = size - 0 - 0;
    const uint8_t* interior = frame + 0;
    f->body = interior + 0;
    f->body_size = interior_n - 0 - 0;
    return GMSG_OK;
}

/* Decode the message view selected by the frame's type id (message_type). */
static gmsg_error sensirion_sht4x_measurement_response_select_(const sensirion_sht4x_measurement_response_frame_* f, sensirion_sht4x_measurement_response_any_view* out) {
    out->kind = SENSIRION_SHT4X_MEASUREMENT_RESPONSE_MEASUREMENT;
    return sensirion_sht4x_measurement_view_from(f->body, f->body_size, &out->as.measurement);
}

static void sensirion_sht4x_measurement_response_deliver_(const sensirion_sht4x_measurement_response_callbacks* cb, const sensirion_sht4x_measurement_response_frame_* f, const sensirion_sht4x_measurement_response_any_view* v) {
    (void)f;
    switch (v->kind) {
        case SENSIRION_SHT4X_MEASUREMENT_RESPONSE_MEASUREMENT: if (cb->on_measurement) cb->on_measurement(cb->ctx, &v->as.measurement); break;
        default: break;
    }
    if (cb->on_frame) cb->on_frame(cb->ctx, v);
}

/* Validate a complete frame, select its message and deliver it (C++: P::process). */
static gmsg_error sensirion_sht4x_measurement_response_process_frame_(const uint8_t* frame, size_t size, const sensirion_sht4x_measurement_response_callbacks* cb) {
    sensirion_sht4x_measurement_response_frame_ f;
    sensirion_sht4x_measurement_response_any_view v;
    gmsg_error e = GMSG_OK;
    if ((e = sensirion_sht4x_measurement_response_open_(frame, size, &f)) != GMSG_OK) return e;
    if ((e = sensirion_sht4x_measurement_response_select_(&f, &v)) != GMSG_OK) return e;
    if (cb) sensirion_sht4x_measurement_response_deliver_(cb, &f, &v);
    return GMSG_OK;
}

gmsg_error sensirion_sht4x_measurement_response_parse(const uint8_t* data, size_t size, sensirion_sht4x_measurement_response_any_view* out) {
    sensirion_sht4x_measurement_response_frame_ f;
    gmsg_error e = GMSG_OK;
    const gmsg_frame_scan s = sensirion_sht4x_measurement_response_scan_(data, size);
    if (s.kind == GMSG_SCAN_NEED_MORE) return GMSG_ERR_TRUNCATED;
    if (s.kind == GMSG_SCAN_SKIP) return s.error == GMSG_OK ? GMSG_ERR_BAD_SYNC : s.error;
    if ((e = sensirion_sht4x_measurement_response_open_(data, s.size, &f)) != GMSG_OK) return e;
    return sensirion_sht4x_measurement_response_select_(&f, out);
}

gmsg_error sensirion_sht4x_measurement_response_decode(const uint8_t* data, size_t size, sensirion_sht4x_measurement_response_any_message* out) {
    sensirion_sht4x_measurement_response_any_view v;
    gmsg_error e = GMSG_OK;
    if ((e = sensirion_sht4x_measurement_response_parse(data, size, &v)) != GMSG_OK) return e;
    out->kind = v.kind;
    switch (v.kind) {
        case SENSIRION_SHT4X_MEASUREMENT_RESPONSE_MEASUREMENT: return sensirion_sht4x_measurement_view_to_struct(&v.as.measurement, &out->as.measurement);
        default: return GMSG_ERR_UNKNOWN_TYPE;
    }
}

gmsg_error sensirion_sht4x_measurement_response_process(const uint8_t* data, size_t size, const sensirion_sht4x_measurement_response_callbacks* cb) {
    const gmsg_frame_scan s = sensirion_sht4x_measurement_response_scan_(data, size);
    if (s.kind == GMSG_SCAN_NEED_MORE) return GMSG_ERR_TRUNCATED;
    if (s.kind == GMSG_SCAN_SKIP) return s.error == GMSG_OK ? GMSG_ERR_BAD_SYNC : s.error;
    return sensirion_sht4x_measurement_response_process_frame_(data, s.size, cb);
}

/* stream modes: deliver to callbacks (feed / next), or capture for the pull API */
enum { sensirion_sht4x_measurement_response_mode_deliver_ = 0, sensirion_sht4x_measurement_response_mode_capture_ = 1, sensirion_sht4x_measurement_response_mode_message_ = 2, sensirion_sht4x_measurement_response_mode_for_ = 3, sensirion_sht4x_measurement_response_mode_wait_ = 4 };

/* Data after the message (bytes, or tokens for text messages). */
static size_t sensirion_sht4x_measurement_response_extra_(const sensirion_sht4x_measurement_response_any_view* v) {
    switch (v->kind) {
        case SENSIRION_SHT4X_MEASUREMENT_RESPONSE_MEASUREMENT: return sensirion_sht4x_measurement_view_extra_bytes(&v->as.measurement);
        default: return 0;
    }
}

static gmsg_error sensirion_sht4x_measurement_response_view_to_message_(const sensirion_sht4x_measurement_response_any_view* v, sensirion_sht4x_measurement_response_any_message* out) {
    out->kind = v->kind;
    switch (v->kind) {
        case SENSIRION_SHT4X_MEASUREMENT_RESPONSE_MEASUREMENT: return sensirion_sht4x_measurement_view_to_struct(&v->as.measurement, &out->as.measurement);
        default: return GMSG_ERR_UNKNOWN_TYPE;
    }
}

/* Mark a request done and queue its callback. */
static void sensirion_sht4x_measurement_response_complete_(sensirion_sht4x_measurement_response_stream* s, sensirion_sht4x_measurement_response_request* r, gmsg_error e) {
    sensirion_sht4x_measurement_response_request** at = &s->completed_;
    r->state = GMSG_REQUEST_DONE;
    r->error = e;
    r->next_ = NULL;
    while (*at) at = &(*at)->next_;
    *at = r;
}

/* The first waiting request that accepts the frame takes it (a failed decode drops the frame). */
static gmsg_error sensirion_sht4x_measurement_response_offer_(sensirion_sht4x_measurement_response_stream* s, const sensirion_sht4x_measurement_response_frame_* f, const sensirion_sht4x_measurement_response_any_view* v, bool* taken) {
    sensirion_sht4x_measurement_response_request** at;
    (void)f;
    for (at = &s->pending_; *at; at = &(*at)->next_) {
        sensirion_sht4x_measurement_response_request* r = *at;
        gmsg_error e;
        if (r->kind_ != v->kind || (r->match_ && !r->match_(r->match_ctx_, v))) continue;
        if ((e = sensirion_sht4x_measurement_response_view_to_message_(v, &r->reply)) != GMSG_OK) return e;
        *at = r->next_;
        sensirion_sht4x_measurement_response_complete_(s, r, GMSG_OK);
        *taken = true;
        return GMSG_OK;
    }
    return GMSG_OK;
}

static gmsg_error sensirion_sht4x_measurement_response_stream_process_(gmsg_stream* gs, uint8_t* frame, size_t n) {
    sensirion_sht4x_measurement_response_stream* s = (sensirion_sht4x_measurement_response_stream*)gs;
    sensirion_sht4x_measurement_response_frame_ f;
    gmsg_error e = GMSG_OK;
    if ((e = sensirion_sht4x_measurement_response_open_(frame, n, &f)) != GMSG_OK) return e;
    if (s->mode_ == sensirion_sht4x_measurement_response_mode_deliver_) {
        sensirion_sht4x_measurement_response_any_view v;
        if ((e = sensirion_sht4x_measurement_response_select_(&f, &v)) != GMSG_OK) return e;
        gs->last_extra = sensirion_sht4x_measurement_response_extra_(&v);
        if (s->pending_) {
            bool taken = false;
            if ((e = sensirion_sht4x_measurement_response_offer_(s, &f, &v, &taken)) != GMSG_OK) {
                return e;
            }
            if (taken) return GMSG_OK;
        }
        sensirion_sht4x_measurement_response_deliver_(&s->cb, &f, &v);
        return GMSG_OK;
    }
    if ((e = sensirion_sht4x_measurement_response_select_(&f, &s->got_.message)) != GMSG_OK) return e;
    gs->last_extra = s->got_.extra = sensirion_sht4x_measurement_response_extra_(&s->got_.message);
    s->got_.bytes = frame;
    s->got_.size = n;
    if (s->mode_ == sensirion_sht4x_measurement_response_mode_for_ && s->got_.message.kind != s->want_) {
        sensirion_sht4x_measurement_response_deliver_(&s->cb, &f, &s->got_.message);  /* not the awaited message: to the callbacks */
        s->got_.message.kind = SENSIRION_SHT4X_MEASUREMENT_RESPONSE_NONE;
    }
    if (s->mode_ == sensirion_sht4x_measurement_response_mode_wait_) {
        if (s->got_.message.kind != s->want_ || (s->match_ && !s->match_(s->match_ctx_, &s->got_.message))) {
            if (s->pending_) {
                bool taken = false;
                if ((e = sensirion_sht4x_measurement_response_offer_(s, &f, &s->got_.message, &taken)) != GMSG_OK) {
                    return e;
                }
                if (taken) s->got_.message.kind = SENSIRION_SHT4X_MEASUREMENT_RESPONSE_NONE;
                if (taken) return GMSG_OK;
            }
            sensirion_sht4x_measurement_response_deliver_(&s->cb, &f, &s->got_.message);  /* not the awaited message: to the callbacks */
            s->got_.message.kind = SENSIRION_SHT4X_MEASUREMENT_RESPONSE_NONE;
            return GMSG_OK;
        }
    }
    if (s->mode_ == sensirion_sht4x_measurement_response_mode_message_ || s->mode_ == sensirion_sht4x_measurement_response_mode_wait_) {
        switch (s->got_.message.kind) {
            case SENSIRION_SHT4X_MEASUREMENT_RESPONSE_MEASUREMENT: s->msg_->kind = SENSIRION_SHT4X_MEASUREMENT_RESPONSE_MEASUREMENT; return sensirion_sht4x_measurement_view_to_struct(&s->got_.message.as.measurement, &s->msg_->as.measurement);
            default: return GMSG_ERR_UNKNOWN_TYPE;
        }
    }
    return GMSG_OK;
}

bool sensirion_sht4x_measurement_response_stream_poll(sensirion_sht4x_measurement_response_stream* s, sensirion_sht4x_measurement_response_any_view* out) {
    bool ok;
    s->mode_ = sensirion_sht4x_measurement_response_mode_capture_;
    ok = gmsg_stream_pull(&s->base);
    s->mode_ = sensirion_sht4x_measurement_response_mode_deliver_;
    if (ok) *out = s->got_.message;
    return ok;
}

bool sensirion_sht4x_measurement_response_stream_poll_frame(sensirion_sht4x_measurement_response_stream* s, sensirion_sht4x_measurement_response_received* out) {
    bool ok;
    s->mode_ = sensirion_sht4x_measurement_response_mode_capture_;
    ok = gmsg_stream_pull(&s->base);
    s->mode_ = sensirion_sht4x_measurement_response_mode_deliver_;
    if (ok) *out = s->got_;
    return ok;
}

bool sensirion_sht4x_measurement_response_stream_poll_message(sensirion_sht4x_measurement_response_stream* s, sensirion_sht4x_measurement_response_any_message* out) {
    bool ok;
    s->mode_ = sensirion_sht4x_measurement_response_mode_message_;
    s->msg_ = out;
    ok = gmsg_stream_pull(&s->base);
    s->mode_ = sensirion_sht4x_measurement_response_mode_deliver_;
    s->msg_ = NULL;
    return ok;
}

gmsg_poll sensirion_sht4x_measurement_response_stream_poll_event(sensirion_sht4x_measurement_response_stream* s, sensirion_sht4x_measurement_response_event* out) {
    gmsg_step step;
    s->mode_ = sensirion_sht4x_measurement_response_mode_capture_;
    step = gmsg_stream_step(&s->base);
    s->mode_ = sensirion_sht4x_measurement_response_mode_deliver_;
    if (step.kind == GMSG_STEP_NEED_MORE) return GMSG_POLL_NEED_MORE;
    if (step.kind == GMSG_STEP_ERROR) {
        out->message.kind = SENSIRION_SHT4X_MEASUREMENT_RESPONSE_NONE;
        out->error = step.error;
        out->data = step.data;
        out->size = step.size;
        return GMSG_POLL_ERROR;
    }
    out->message = s->got_.message;
    out->error = GMSG_OK;
    out->data = NULL;
    out->size = 0;
    return GMSG_POLL_MESSAGE;
}

bool sensirion_sht4x_measurement_response_stream_poll_for(sensirion_sht4x_measurement_response_stream* s, sensirion_sht4x_measurement_response_kind kind, sensirion_sht4x_measurement_response_any_view* out) {
    bool hit = false;
    s->mode_ = sensirion_sht4x_measurement_response_mode_for_;
    s->want_ = kind;
    while (gmsg_stream_pull(&s->base)) {
        if (s->got_.message.kind == kind) {
            *out = s->got_.message;
            hit = true;
            break;
        }
    }
    s->mode_ = sensirion_sht4x_measurement_response_mode_deliver_;
    return hit;
}

static void sensirion_sht4x_measurement_response_stream_error_(gmsg_stream* s, gmsg_error e, const uint8_t* data, size_t n) {
    const sensirion_sht4x_measurement_response_callbacks* cb = &((sensirion_sht4x_measurement_response_stream*)s)->cb;
    if (cb->on_error) cb->on_error(cb->ctx, e, data, n);
}

gmsg_error sensirion_sht4x_measurement_response_stream_init(sensirion_sht4x_measurement_response_stream* s, uint8_t* buf, size_t size) {
    gmsg_memset(s, 0, sizeof *s);  /* callbacks cleared, deliver mode */
    return gmsg_stream_init(&s->base, buf, size, SENSIRION_SHT4X_MEASUREMENT_RESPONSE_MAX_FRAME, sensirion_sht4x_measurement_response_scan_, sensirion_sht4x_measurement_response_stream_process_, sensirion_sht4x_measurement_response_stream_error_);
}

/* run the callbacks of finished requests (after a step, so a callback may start the next request) */
static void sensirion_sht4x_measurement_response_endpoint_fire_(gmsg_endpoint* io) {
    sensirion_sht4x_measurement_response_stream* s = &((sensirion_sht4x_measurement_response_endpoint*)(void*)((char*)io - offsetof(sensirion_sht4x_measurement_response_endpoint, io)))->stream;
    while (s->completed_) {
        sensirion_sht4x_measurement_response_request* r = s->completed_;
        s->completed_ = r->next_;
        r->next_ = NULL;
        if (r->on_done_) r->on_done_(r->ctx_, r);
    }
}

static void sensirion_sht4x_measurement_response_endpoint_expire_(gmsg_endpoint* io) {
    sensirion_sht4x_measurement_response_stream* s = &((sensirion_sht4x_measurement_response_endpoint*)(void*)((char*)io - offsetof(sensirion_sht4x_measurement_response_endpoint, io)))->stream;
    const uint32_t now = gmsg_endpoint_now(io);
    sensirion_sht4x_measurement_response_request** at = &s->pending_;
    while (*at) {
        sensirion_sht4x_measurement_response_request* r = *at;
        if ((uint32_t)(now - r->start_) >= r->timeout_) {
            *at = r->next_;
            sensirion_sht4x_measurement_response_complete_(s, r, GMSG_ERR_TIMEOUT);
        } else {
            at = &r->next_;
        }
    }
    sensirion_sht4x_measurement_response_endpoint_fire_(io);
}

gmsg_error sensirion_sht4x_measurement_response_endpoint_init(sensirion_sht4x_measurement_response_endpoint* ep, uint8_t* buf, size_t size, const gmsg_source* source, const gmsg_sink* sink) {
    const gmsg_error e = sensirion_sht4x_measurement_response_stream_init(&ep->stream, buf, size);
    gmsg_endpoint_init(&ep->io, &ep->stream.base, source, sink);
    ep->io.on_step = sensirion_sht4x_measurement_response_endpoint_fire_;
    ep->io.on_tick = sensirion_sht4x_measurement_response_endpoint_expire_;
    return e;
}

void sensirion_sht4x_measurement_response_endpoint_cancel(sensirion_sht4x_measurement_response_endpoint* ep, sensirion_sht4x_measurement_response_request* r) {
    sensirion_sht4x_measurement_response_request** at = &ep->stream.pending_;
    while (*at && *at != r) at = &(*at)->next_;
    if (*at) {
        *at = r->next_;
        r->next_ = NULL;
    }
    if (r->state == GMSG_REQUEST_WAITING) r->state = GMSG_REQUEST_IDLE;
}

void sensirion_sht4x_measurement_response_endpoint_expect(sensirion_sht4x_measurement_response_endpoint* ep, sensirion_sht4x_measurement_response_request* r, sensirion_sht4x_measurement_response_kind kind, uint32_t timeout, sensirion_sht4x_measurement_response_match_fn match, void* match_ctx, sensirion_sht4x_measurement_response_request_fn on_done, void* ctx) {
    sensirion_sht4x_measurement_response_request** at;
    sensirion_sht4x_measurement_response_endpoint_cancel(ep, r);
    r->state = GMSG_REQUEST_WAITING;
    r->error = GMSG_OK;
    r->kind_ = kind;
    r->match_ = match;
    r->match_ctx_ = match_ctx;
    r->on_done_ = on_done;
    r->ctx_ = ctx;
    r->start_ = gmsg_endpoint_now(&ep->io);
    r->timeout_ = timeout;
    r->next_ = NULL;
    at = &ep->stream.pending_;
    while (*at) at = &(*at)->next_;
    *at = r;
}

size_t sensirion_sht4x_measurement_response_endpoint_pending(const sensirion_sht4x_measurement_response_endpoint* ep) {
    size_t k = 0;
    const sensirion_sht4x_measurement_response_request* r;
    for (r = ep->stream.pending_; r; r = r->next_) ++k;
    return k;
}

gmsg_error sensirion_sht4x_measurement_response_endpoint_send_measurement(sensirion_sht4x_measurement_response_endpoint* ep, const sensirion_sht4x_measurement* m) {
    size_t n = 0;
    const gmsg_error e = sensirion_sht4x_measurement_response_encode_measurement(m, ep->tx, sizeof ep->tx, &n);
    return e != GMSG_OK ? e : gmsg_endpoint_write(&ep->io, ep->tx, n);
}

gmsg_error sensirion_sht4x_measurement_response_endpoint_send(sensirion_sht4x_measurement_response_endpoint* ep, const sensirion_sht4x_measurement_response_any_message* m) {
    size_t n = 0;
    const gmsg_error e = sensirion_sht4x_measurement_response_encode(m, ep->tx, sizeof ep->tx, &n);
    return e != GMSG_OK ? e : gmsg_endpoint_write(&ep->io, ep->tx, n);
}

static bool sensirion_sht4x_measurement_response_endpoint_pull_(void* ctx) {
    sensirion_sht4x_measurement_response_endpoint* ep = (sensirion_sht4x_measurement_response_endpoint*)ctx;
    sensirion_sht4x_measurement_response_stream* s = &ep->stream;
    while (gmsg_stream_pull(&s->base)) {
        sensirion_sht4x_measurement_response_endpoint_fire_(&ep->io);
        if (s->got_.message.kind == s->want_) return true;
    }
    return false;
}

gmsg_error sensirion_sht4x_measurement_response_endpoint_wait_for(sensirion_sht4x_measurement_response_endpoint* ep, sensirion_sht4x_measurement_response_kind kind, uint32_t timeout, sensirion_sht4x_measurement_response_match_fn match, void* match_ctx, sensirion_sht4x_measurement_response_any_message* out) {
    sensirion_sht4x_measurement_response_stream* s = &ep->stream;
    gmsg_error e;
    s->mode_ = sensirion_sht4x_measurement_response_mode_wait_;
    s->want_ = kind;
    s->match_ = match;
    s->match_ctx_ = match_ctx;
    s->msg_ = out;
    e = gmsg_endpoint_wait(&ep->io, timeout, sensirion_sht4x_measurement_response_endpoint_pull_, ep);
    s->mode_ = sensirion_sht4x_measurement_response_mode_deliver_;
    s->match_ = NULL;
    s->match_ctx_ = NULL;
    s->msg_ = NULL;
    return e;
}

gmsg_error sensirion_sht4x_measurement_response_endpoint_transact(sensirion_sht4x_measurement_response_endpoint* ep, const sensirion_sht4x_measurement_response_any_message* request, sensirion_sht4x_measurement_response_kind kind, uint32_t timeout, sensirion_sht4x_measurement_response_match_fn match, void* match_ctx, sensirion_sht4x_measurement_response_any_message* out) {
    gmsg_error e = GMSG_OK;
    (void)gmsg_endpoint_service(&ep->io, SIZE_MAX);  /* frames that arrived before go to the callbacks */
    e = sensirion_sht4x_measurement_response_endpoint_send(ep, request);
    if (e != GMSG_OK) return e;
    return sensirion_sht4x_measurement_response_endpoint_wait_for(ep, kind, timeout, match, match_ctx, out);
}

gmsg_error sensirion_sht4x_measurement_response_endpoint_request(sensirion_sht4x_measurement_response_endpoint* ep, sensirion_sht4x_measurement_response_request* r, const sensirion_sht4x_measurement_response_any_message* request, sensirion_sht4x_measurement_response_kind kind, uint32_t timeout, sensirion_sht4x_measurement_response_match_fn match, void* match_ctx, sensirion_sht4x_measurement_response_request_fn on_done, void* ctx) {
    gmsg_error e = GMSG_OK;
    sensirion_sht4x_measurement_response_endpoint_cancel(ep, r);
    if (ep->io.depth == 0) (void)gmsg_endpoint_service(&ep->io, SIZE_MAX);  /* not from a callback */
    e = sensirion_sht4x_measurement_response_endpoint_send(ep, request);
    if (e != GMSG_OK) return e;
    sensirion_sht4x_measurement_response_endpoint_expect(ep, r, kind, timeout, match, match_ctx, on_done, ctx);
    return GMSG_OK;
}

gmsg_error sensirion_sht4x_measurement_response_encode_measurement(const sensirion_sht4x_measurement* m, uint8_t* out, size_t capacity, size_t* written) {
    gmsg_writer w = gmsg_writer_init(out, capacity);
    gmsg_error e = GMSG_OK;
    if (written) *written = 0;
    const size_t header_at = w.pos;
    (void)header_at;
    const size_t body_at = w.pos;
    if ((e = sensirion_sht4x_measurement_write(m, &w)) != GMSG_OK) return e;
    const size_t body_len = w.pos - body_at;
    (void)body_len;
    if (body_len > 6) return GMSG_ERR_BAD_LENGTH;
    if ((e = gmsg_write_fill(&w, 0, 6 - body_len)) != GMSG_OK) return e;
    size_t total = w.pos;
    if (written) *written = total;
    return GMSG_OK;
}

gmsg_error sensirion_sht4x_measurement_response_encode(const sensirion_sht4x_measurement_response_any_message* m, uint8_t* out, size_t capacity, size_t* written) {
    switch (m->kind) {
        case SENSIRION_SHT4X_MEASUREMENT_RESPONSE_MEASUREMENT: return sensirion_sht4x_measurement_response_encode_measurement(&m->as.measurement, out, capacity, written);
        default: break;
    }
    if (written) *written = 0;
    return GMSG_ERR_UNKNOWN_TYPE;
}

/* ==== protocol SerialNumberResponse ================================================================ */

void sensirion_sht4x_serial_number_response_any_view_print(const sensirion_sht4x_serial_number_response_any_view* v, gmsg_printer* p) {
    switch (v->kind) {
        case SENSIRION_SHT4X_SERIAL_NUMBER_RESPONSE_SERIAL_NUMBER: sensirion_sht4x_serial_number_view_print(&v->as.serial_number, p); break;
        default: gmsg_print_text(p, "<none>", 6); break;
    }
}

void sensirion_sht4x_serial_number_response_any_message_print(const sensirion_sht4x_serial_number_response_any_message* v, gmsg_printer* p) {
    switch (v->kind) {
        case SENSIRION_SHT4X_SERIAL_NUMBER_RESPONSE_SERIAL_NUMBER: sensirion_sht4x_serial_number_print(&v->as.serial_number, p); break;
        default: gmsg_print_text(p, "<none>", 6); break;
    }
}

static const gmsg_fixed_config sensirion_sht4x_serial_number_response_framing_ = {{{0}, 0}, 6, {false, 0, 0, 0, 0, {0}, {0}, {0}}, 0};
static gmsg_frame_scan sensirion_sht4x_serial_number_response_scan_(const uint8_t* b, size_t n) { return gmsg_scan_fixed(b, n, &sensirion_sht4x_serial_number_response_framing_); }

/* A validated frame split into its parts (pointers into the frame buffer). */
typedef struct sensirion_sht4x_serial_number_response_frame_ {
    const uint8_t* body;
    size_t body_size;
} sensirion_sht4x_serial_number_response_frame_;

/* Validate one complete frame (as delimited by the scanner) and split it into header and body. */
static gmsg_error sensirion_sht4x_serial_number_response_open_(const uint8_t* frame, size_t size, sensirion_sht4x_serial_number_response_frame_* f) {
    gmsg_error e = GMSG_OK;
    (void)e;
    const size_t interior_n = size - 0 - 0;
    const uint8_t* interior = frame + 0;
    f->body = interior + 0;
    f->body_size = interior_n - 0 - 0;
    return GMSG_OK;
}

/* Decode the message view selected by the frame's type id (message_type). */
static gmsg_error sensirion_sht4x_serial_number_response_select_(const sensirion_sht4x_serial_number_response_frame_* f, sensirion_sht4x_serial_number_response_any_view* out) {
    out->kind = SENSIRION_SHT4X_SERIAL_NUMBER_RESPONSE_SERIAL_NUMBER;
    return sensirion_sht4x_serial_number_view_from(f->body, f->body_size, &out->as.serial_number);
}

static void sensirion_sht4x_serial_number_response_deliver_(const sensirion_sht4x_serial_number_response_callbacks* cb, const sensirion_sht4x_serial_number_response_frame_* f, const sensirion_sht4x_serial_number_response_any_view* v) {
    (void)f;
    switch (v->kind) {
        case SENSIRION_SHT4X_SERIAL_NUMBER_RESPONSE_SERIAL_NUMBER: if (cb->on_serial_number) cb->on_serial_number(cb->ctx, &v->as.serial_number); break;
        default: break;
    }
    if (cb->on_frame) cb->on_frame(cb->ctx, v);
}

/* Validate a complete frame, select its message and deliver it (C++: P::process). */
static gmsg_error sensirion_sht4x_serial_number_response_process_frame_(const uint8_t* frame, size_t size, const sensirion_sht4x_serial_number_response_callbacks* cb) {
    sensirion_sht4x_serial_number_response_frame_ f;
    sensirion_sht4x_serial_number_response_any_view v;
    gmsg_error e = GMSG_OK;
    if ((e = sensirion_sht4x_serial_number_response_open_(frame, size, &f)) != GMSG_OK) return e;
    if ((e = sensirion_sht4x_serial_number_response_select_(&f, &v)) != GMSG_OK) return e;
    if (cb) sensirion_sht4x_serial_number_response_deliver_(cb, &f, &v);
    return GMSG_OK;
}

gmsg_error sensirion_sht4x_serial_number_response_parse(const uint8_t* data, size_t size, sensirion_sht4x_serial_number_response_any_view* out) {
    sensirion_sht4x_serial_number_response_frame_ f;
    gmsg_error e = GMSG_OK;
    const gmsg_frame_scan s = sensirion_sht4x_serial_number_response_scan_(data, size);
    if (s.kind == GMSG_SCAN_NEED_MORE) return GMSG_ERR_TRUNCATED;
    if (s.kind == GMSG_SCAN_SKIP) return s.error == GMSG_OK ? GMSG_ERR_BAD_SYNC : s.error;
    if ((e = sensirion_sht4x_serial_number_response_open_(data, s.size, &f)) != GMSG_OK) return e;
    return sensirion_sht4x_serial_number_response_select_(&f, out);
}

gmsg_error sensirion_sht4x_serial_number_response_decode(const uint8_t* data, size_t size, sensirion_sht4x_serial_number_response_any_message* out) {
    sensirion_sht4x_serial_number_response_any_view v;
    gmsg_error e = GMSG_OK;
    if ((e = sensirion_sht4x_serial_number_response_parse(data, size, &v)) != GMSG_OK) return e;
    out->kind = v.kind;
    switch (v.kind) {
        case SENSIRION_SHT4X_SERIAL_NUMBER_RESPONSE_SERIAL_NUMBER: return sensirion_sht4x_serial_number_view_to_struct(&v.as.serial_number, &out->as.serial_number);
        default: return GMSG_ERR_UNKNOWN_TYPE;
    }
}

gmsg_error sensirion_sht4x_serial_number_response_process(const uint8_t* data, size_t size, const sensirion_sht4x_serial_number_response_callbacks* cb) {
    const gmsg_frame_scan s = sensirion_sht4x_serial_number_response_scan_(data, size);
    if (s.kind == GMSG_SCAN_NEED_MORE) return GMSG_ERR_TRUNCATED;
    if (s.kind == GMSG_SCAN_SKIP) return s.error == GMSG_OK ? GMSG_ERR_BAD_SYNC : s.error;
    return sensirion_sht4x_serial_number_response_process_frame_(data, s.size, cb);
}

/* stream modes: deliver to callbacks (feed / next), or capture for the pull API */
enum { sensirion_sht4x_serial_number_response_mode_deliver_ = 0, sensirion_sht4x_serial_number_response_mode_capture_ = 1, sensirion_sht4x_serial_number_response_mode_message_ = 2, sensirion_sht4x_serial_number_response_mode_for_ = 3, sensirion_sht4x_serial_number_response_mode_wait_ = 4 };

/* Data after the message (bytes, or tokens for text messages). */
static size_t sensirion_sht4x_serial_number_response_extra_(const sensirion_sht4x_serial_number_response_any_view* v) {
    switch (v->kind) {
        case SENSIRION_SHT4X_SERIAL_NUMBER_RESPONSE_SERIAL_NUMBER: return sensirion_sht4x_serial_number_view_extra_bytes(&v->as.serial_number);
        default: return 0;
    }
}

static gmsg_error sensirion_sht4x_serial_number_response_view_to_message_(const sensirion_sht4x_serial_number_response_any_view* v, sensirion_sht4x_serial_number_response_any_message* out) {
    out->kind = v->kind;
    switch (v->kind) {
        case SENSIRION_SHT4X_SERIAL_NUMBER_RESPONSE_SERIAL_NUMBER: return sensirion_sht4x_serial_number_view_to_struct(&v->as.serial_number, &out->as.serial_number);
        default: return GMSG_ERR_UNKNOWN_TYPE;
    }
}

/* Mark a request done and queue its callback. */
static void sensirion_sht4x_serial_number_response_complete_(sensirion_sht4x_serial_number_response_stream* s, sensirion_sht4x_serial_number_response_request* r, gmsg_error e) {
    sensirion_sht4x_serial_number_response_request** at = &s->completed_;
    r->state = GMSG_REQUEST_DONE;
    r->error = e;
    r->next_ = NULL;
    while (*at) at = &(*at)->next_;
    *at = r;
}

/* The first waiting request that accepts the frame takes it (a failed decode drops the frame). */
static gmsg_error sensirion_sht4x_serial_number_response_offer_(sensirion_sht4x_serial_number_response_stream* s, const sensirion_sht4x_serial_number_response_frame_* f, const sensirion_sht4x_serial_number_response_any_view* v, bool* taken) {
    sensirion_sht4x_serial_number_response_request** at;
    (void)f;
    for (at = &s->pending_; *at; at = &(*at)->next_) {
        sensirion_sht4x_serial_number_response_request* r = *at;
        gmsg_error e;
        if (r->kind_ != v->kind || (r->match_ && !r->match_(r->match_ctx_, v))) continue;
        if ((e = sensirion_sht4x_serial_number_response_view_to_message_(v, &r->reply)) != GMSG_OK) return e;
        *at = r->next_;
        sensirion_sht4x_serial_number_response_complete_(s, r, GMSG_OK);
        *taken = true;
        return GMSG_OK;
    }
    return GMSG_OK;
}

static gmsg_error sensirion_sht4x_serial_number_response_stream_process_(gmsg_stream* gs, uint8_t* frame, size_t n) {
    sensirion_sht4x_serial_number_response_stream* s = (sensirion_sht4x_serial_number_response_stream*)gs;
    sensirion_sht4x_serial_number_response_frame_ f;
    gmsg_error e = GMSG_OK;
    if ((e = sensirion_sht4x_serial_number_response_open_(frame, n, &f)) != GMSG_OK) return e;
    if (s->mode_ == sensirion_sht4x_serial_number_response_mode_deliver_) {
        sensirion_sht4x_serial_number_response_any_view v;
        if ((e = sensirion_sht4x_serial_number_response_select_(&f, &v)) != GMSG_OK) return e;
        gs->last_extra = sensirion_sht4x_serial_number_response_extra_(&v);
        if (s->pending_) {
            bool taken = false;
            if ((e = sensirion_sht4x_serial_number_response_offer_(s, &f, &v, &taken)) != GMSG_OK) {
                return e;
            }
            if (taken) return GMSG_OK;
        }
        sensirion_sht4x_serial_number_response_deliver_(&s->cb, &f, &v);
        return GMSG_OK;
    }
    if ((e = sensirion_sht4x_serial_number_response_select_(&f, &s->got_.message)) != GMSG_OK) return e;
    gs->last_extra = s->got_.extra = sensirion_sht4x_serial_number_response_extra_(&s->got_.message);
    s->got_.bytes = frame;
    s->got_.size = n;
    if (s->mode_ == sensirion_sht4x_serial_number_response_mode_for_ && s->got_.message.kind != s->want_) {
        sensirion_sht4x_serial_number_response_deliver_(&s->cb, &f, &s->got_.message);  /* not the awaited message: to the callbacks */
        s->got_.message.kind = SENSIRION_SHT4X_SERIAL_NUMBER_RESPONSE_NONE;
    }
    if (s->mode_ == sensirion_sht4x_serial_number_response_mode_wait_) {
        if (s->got_.message.kind != s->want_ || (s->match_ && !s->match_(s->match_ctx_, &s->got_.message))) {
            if (s->pending_) {
                bool taken = false;
                if ((e = sensirion_sht4x_serial_number_response_offer_(s, &f, &s->got_.message, &taken)) != GMSG_OK) {
                    return e;
                }
                if (taken) s->got_.message.kind = SENSIRION_SHT4X_SERIAL_NUMBER_RESPONSE_NONE;
                if (taken) return GMSG_OK;
            }
            sensirion_sht4x_serial_number_response_deliver_(&s->cb, &f, &s->got_.message);  /* not the awaited message: to the callbacks */
            s->got_.message.kind = SENSIRION_SHT4X_SERIAL_NUMBER_RESPONSE_NONE;
            return GMSG_OK;
        }
    }
    if (s->mode_ == sensirion_sht4x_serial_number_response_mode_message_ || s->mode_ == sensirion_sht4x_serial_number_response_mode_wait_) {
        switch (s->got_.message.kind) {
            case SENSIRION_SHT4X_SERIAL_NUMBER_RESPONSE_SERIAL_NUMBER: s->msg_->kind = SENSIRION_SHT4X_SERIAL_NUMBER_RESPONSE_SERIAL_NUMBER; return sensirion_sht4x_serial_number_view_to_struct(&s->got_.message.as.serial_number, &s->msg_->as.serial_number);
            default: return GMSG_ERR_UNKNOWN_TYPE;
        }
    }
    return GMSG_OK;
}

bool sensirion_sht4x_serial_number_response_stream_poll(sensirion_sht4x_serial_number_response_stream* s, sensirion_sht4x_serial_number_response_any_view* out) {
    bool ok;
    s->mode_ = sensirion_sht4x_serial_number_response_mode_capture_;
    ok = gmsg_stream_pull(&s->base);
    s->mode_ = sensirion_sht4x_serial_number_response_mode_deliver_;
    if (ok) *out = s->got_.message;
    return ok;
}

bool sensirion_sht4x_serial_number_response_stream_poll_frame(sensirion_sht4x_serial_number_response_stream* s, sensirion_sht4x_serial_number_response_received* out) {
    bool ok;
    s->mode_ = sensirion_sht4x_serial_number_response_mode_capture_;
    ok = gmsg_stream_pull(&s->base);
    s->mode_ = sensirion_sht4x_serial_number_response_mode_deliver_;
    if (ok) *out = s->got_;
    return ok;
}

bool sensirion_sht4x_serial_number_response_stream_poll_message(sensirion_sht4x_serial_number_response_stream* s, sensirion_sht4x_serial_number_response_any_message* out) {
    bool ok;
    s->mode_ = sensirion_sht4x_serial_number_response_mode_message_;
    s->msg_ = out;
    ok = gmsg_stream_pull(&s->base);
    s->mode_ = sensirion_sht4x_serial_number_response_mode_deliver_;
    s->msg_ = NULL;
    return ok;
}

gmsg_poll sensirion_sht4x_serial_number_response_stream_poll_event(sensirion_sht4x_serial_number_response_stream* s, sensirion_sht4x_serial_number_response_event* out) {
    gmsg_step step;
    s->mode_ = sensirion_sht4x_serial_number_response_mode_capture_;
    step = gmsg_stream_step(&s->base);
    s->mode_ = sensirion_sht4x_serial_number_response_mode_deliver_;
    if (step.kind == GMSG_STEP_NEED_MORE) return GMSG_POLL_NEED_MORE;
    if (step.kind == GMSG_STEP_ERROR) {
        out->message.kind = SENSIRION_SHT4X_SERIAL_NUMBER_RESPONSE_NONE;
        out->error = step.error;
        out->data = step.data;
        out->size = step.size;
        return GMSG_POLL_ERROR;
    }
    out->message = s->got_.message;
    out->error = GMSG_OK;
    out->data = NULL;
    out->size = 0;
    return GMSG_POLL_MESSAGE;
}

bool sensirion_sht4x_serial_number_response_stream_poll_for(sensirion_sht4x_serial_number_response_stream* s, sensirion_sht4x_serial_number_response_kind kind, sensirion_sht4x_serial_number_response_any_view* out) {
    bool hit = false;
    s->mode_ = sensirion_sht4x_serial_number_response_mode_for_;
    s->want_ = kind;
    while (gmsg_stream_pull(&s->base)) {
        if (s->got_.message.kind == kind) {
            *out = s->got_.message;
            hit = true;
            break;
        }
    }
    s->mode_ = sensirion_sht4x_serial_number_response_mode_deliver_;
    return hit;
}

static void sensirion_sht4x_serial_number_response_stream_error_(gmsg_stream* s, gmsg_error e, const uint8_t* data, size_t n) {
    const sensirion_sht4x_serial_number_response_callbacks* cb = &((sensirion_sht4x_serial_number_response_stream*)s)->cb;
    if (cb->on_error) cb->on_error(cb->ctx, e, data, n);
}

gmsg_error sensirion_sht4x_serial_number_response_stream_init(sensirion_sht4x_serial_number_response_stream* s, uint8_t* buf, size_t size) {
    gmsg_memset(s, 0, sizeof *s);  /* callbacks cleared, deliver mode */
    return gmsg_stream_init(&s->base, buf, size, SENSIRION_SHT4X_SERIAL_NUMBER_RESPONSE_MAX_FRAME, sensirion_sht4x_serial_number_response_scan_, sensirion_sht4x_serial_number_response_stream_process_, sensirion_sht4x_serial_number_response_stream_error_);
}

/* run the callbacks of finished requests (after a step, so a callback may start the next request) */
static void sensirion_sht4x_serial_number_response_endpoint_fire_(gmsg_endpoint* io) {
    sensirion_sht4x_serial_number_response_stream* s = &((sensirion_sht4x_serial_number_response_endpoint*)(void*)((char*)io - offsetof(sensirion_sht4x_serial_number_response_endpoint, io)))->stream;
    while (s->completed_) {
        sensirion_sht4x_serial_number_response_request* r = s->completed_;
        s->completed_ = r->next_;
        r->next_ = NULL;
        if (r->on_done_) r->on_done_(r->ctx_, r);
    }
}

static void sensirion_sht4x_serial_number_response_endpoint_expire_(gmsg_endpoint* io) {
    sensirion_sht4x_serial_number_response_stream* s = &((sensirion_sht4x_serial_number_response_endpoint*)(void*)((char*)io - offsetof(sensirion_sht4x_serial_number_response_endpoint, io)))->stream;
    const uint32_t now = gmsg_endpoint_now(io);
    sensirion_sht4x_serial_number_response_request** at = &s->pending_;
    while (*at) {
        sensirion_sht4x_serial_number_response_request* r = *at;
        if ((uint32_t)(now - r->start_) >= r->timeout_) {
            *at = r->next_;
            sensirion_sht4x_serial_number_response_complete_(s, r, GMSG_ERR_TIMEOUT);
        } else {
            at = &r->next_;
        }
    }
    sensirion_sht4x_serial_number_response_endpoint_fire_(io);
}

gmsg_error sensirion_sht4x_serial_number_response_endpoint_init(sensirion_sht4x_serial_number_response_endpoint* ep, uint8_t* buf, size_t size, const gmsg_source* source, const gmsg_sink* sink) {
    const gmsg_error e = sensirion_sht4x_serial_number_response_stream_init(&ep->stream, buf, size);
    gmsg_endpoint_init(&ep->io, &ep->stream.base, source, sink);
    ep->io.on_step = sensirion_sht4x_serial_number_response_endpoint_fire_;
    ep->io.on_tick = sensirion_sht4x_serial_number_response_endpoint_expire_;
    return e;
}

void sensirion_sht4x_serial_number_response_endpoint_cancel(sensirion_sht4x_serial_number_response_endpoint* ep, sensirion_sht4x_serial_number_response_request* r) {
    sensirion_sht4x_serial_number_response_request** at = &ep->stream.pending_;
    while (*at && *at != r) at = &(*at)->next_;
    if (*at) {
        *at = r->next_;
        r->next_ = NULL;
    }
    if (r->state == GMSG_REQUEST_WAITING) r->state = GMSG_REQUEST_IDLE;
}

void sensirion_sht4x_serial_number_response_endpoint_expect(sensirion_sht4x_serial_number_response_endpoint* ep, sensirion_sht4x_serial_number_response_request* r, sensirion_sht4x_serial_number_response_kind kind, uint32_t timeout, sensirion_sht4x_serial_number_response_match_fn match, void* match_ctx, sensirion_sht4x_serial_number_response_request_fn on_done, void* ctx) {
    sensirion_sht4x_serial_number_response_request** at;
    sensirion_sht4x_serial_number_response_endpoint_cancel(ep, r);
    r->state = GMSG_REQUEST_WAITING;
    r->error = GMSG_OK;
    r->kind_ = kind;
    r->match_ = match;
    r->match_ctx_ = match_ctx;
    r->on_done_ = on_done;
    r->ctx_ = ctx;
    r->start_ = gmsg_endpoint_now(&ep->io);
    r->timeout_ = timeout;
    r->next_ = NULL;
    at = &ep->stream.pending_;
    while (*at) at = &(*at)->next_;
    *at = r;
}

size_t sensirion_sht4x_serial_number_response_endpoint_pending(const sensirion_sht4x_serial_number_response_endpoint* ep) {
    size_t k = 0;
    const sensirion_sht4x_serial_number_response_request* r;
    for (r = ep->stream.pending_; r; r = r->next_) ++k;
    return k;
}

gmsg_error sensirion_sht4x_serial_number_response_endpoint_send_serial_number(sensirion_sht4x_serial_number_response_endpoint* ep, const sensirion_sht4x_serial_number* m) {
    size_t n = 0;
    const gmsg_error e = sensirion_sht4x_serial_number_response_encode_serial_number(m, ep->tx, sizeof ep->tx, &n);
    return e != GMSG_OK ? e : gmsg_endpoint_write(&ep->io, ep->tx, n);
}

gmsg_error sensirion_sht4x_serial_number_response_endpoint_send(sensirion_sht4x_serial_number_response_endpoint* ep, const sensirion_sht4x_serial_number_response_any_message* m) {
    size_t n = 0;
    const gmsg_error e = sensirion_sht4x_serial_number_response_encode(m, ep->tx, sizeof ep->tx, &n);
    return e != GMSG_OK ? e : gmsg_endpoint_write(&ep->io, ep->tx, n);
}

static bool sensirion_sht4x_serial_number_response_endpoint_pull_(void* ctx) {
    sensirion_sht4x_serial_number_response_endpoint* ep = (sensirion_sht4x_serial_number_response_endpoint*)ctx;
    sensirion_sht4x_serial_number_response_stream* s = &ep->stream;
    while (gmsg_stream_pull(&s->base)) {
        sensirion_sht4x_serial_number_response_endpoint_fire_(&ep->io);
        if (s->got_.message.kind == s->want_) return true;
    }
    return false;
}

gmsg_error sensirion_sht4x_serial_number_response_endpoint_wait_for(sensirion_sht4x_serial_number_response_endpoint* ep, sensirion_sht4x_serial_number_response_kind kind, uint32_t timeout, sensirion_sht4x_serial_number_response_match_fn match, void* match_ctx, sensirion_sht4x_serial_number_response_any_message* out) {
    sensirion_sht4x_serial_number_response_stream* s = &ep->stream;
    gmsg_error e;
    s->mode_ = sensirion_sht4x_serial_number_response_mode_wait_;
    s->want_ = kind;
    s->match_ = match;
    s->match_ctx_ = match_ctx;
    s->msg_ = out;
    e = gmsg_endpoint_wait(&ep->io, timeout, sensirion_sht4x_serial_number_response_endpoint_pull_, ep);
    s->mode_ = sensirion_sht4x_serial_number_response_mode_deliver_;
    s->match_ = NULL;
    s->match_ctx_ = NULL;
    s->msg_ = NULL;
    return e;
}

gmsg_error sensirion_sht4x_serial_number_response_endpoint_transact(sensirion_sht4x_serial_number_response_endpoint* ep, const sensirion_sht4x_serial_number_response_any_message* request, sensirion_sht4x_serial_number_response_kind kind, uint32_t timeout, sensirion_sht4x_serial_number_response_match_fn match, void* match_ctx, sensirion_sht4x_serial_number_response_any_message* out) {
    gmsg_error e = GMSG_OK;
    (void)gmsg_endpoint_service(&ep->io, SIZE_MAX);  /* frames that arrived before go to the callbacks */
    e = sensirion_sht4x_serial_number_response_endpoint_send(ep, request);
    if (e != GMSG_OK) return e;
    return sensirion_sht4x_serial_number_response_endpoint_wait_for(ep, kind, timeout, match, match_ctx, out);
}

gmsg_error sensirion_sht4x_serial_number_response_endpoint_request(sensirion_sht4x_serial_number_response_endpoint* ep, sensirion_sht4x_serial_number_response_request* r, const sensirion_sht4x_serial_number_response_any_message* request, sensirion_sht4x_serial_number_response_kind kind, uint32_t timeout, sensirion_sht4x_serial_number_response_match_fn match, void* match_ctx, sensirion_sht4x_serial_number_response_request_fn on_done, void* ctx) {
    gmsg_error e = GMSG_OK;
    sensirion_sht4x_serial_number_response_endpoint_cancel(ep, r);
    if (ep->io.depth == 0) (void)gmsg_endpoint_service(&ep->io, SIZE_MAX);  /* not from a callback */
    e = sensirion_sht4x_serial_number_response_endpoint_send(ep, request);
    if (e != GMSG_OK) return e;
    sensirion_sht4x_serial_number_response_endpoint_expect(ep, r, kind, timeout, match, match_ctx, on_done, ctx);
    return GMSG_OK;
}

gmsg_error sensirion_sht4x_serial_number_response_encode_serial_number(const sensirion_sht4x_serial_number* m, uint8_t* out, size_t capacity, size_t* written) {
    gmsg_writer w = gmsg_writer_init(out, capacity);
    gmsg_error e = GMSG_OK;
    if (written) *written = 0;
    const size_t header_at = w.pos;
    (void)header_at;
    const size_t body_at = w.pos;
    if ((e = sensirion_sht4x_serial_number_write(m, &w)) != GMSG_OK) return e;
    const size_t body_len = w.pos - body_at;
    (void)body_len;
    if (body_len > 6) return GMSG_ERR_BAD_LENGTH;
    if ((e = gmsg_write_fill(&w, 0, 6 - body_len)) != GMSG_OK) return e;
    size_t total = w.pos;
    if (written) *written = total;
    return GMSG_OK;
}

gmsg_error sensirion_sht4x_serial_number_response_encode(const sensirion_sht4x_serial_number_response_any_message* m, uint8_t* out, size_t capacity, size_t* written) {
    switch (m->kind) {
        case SENSIRION_SHT4X_SERIAL_NUMBER_RESPONSE_SERIAL_NUMBER: return sensirion_sht4x_serial_number_response_encode_serial_number(&m->as.serial_number, out, capacity, written);
        default: break;
    }
    if (written) *written = 0;
    return GMSG_ERR_UNKNOWN_TYPE;
}

